CREATE TABLE IF NOT EXISTS "xstore_poultry_farm_lots" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,"tenant_id" uuid NOT NULL REFERENCES "xstore_tenants"("id") ON DELETE cascade,"product_name" text NOT NULL,"received_kg" numeric(12,3) NOT NULL,"remaining_kg" numeric(12,3) NOT NULL,"unit_cost" numeric(12,2) NOT NULL,"note" text,"created_at" timestamptz DEFAULT now() NOT NULL);
CREATE INDEX IF NOT EXISTS "xstore_poultry_farm_lots_tenant_product_created_idx" ON "xstore_poultry_farm_lots" ("tenant_id","product_name","created_at");
CREATE INDEX IF NOT EXISTS "xstore_poultry_farm_lots_tenant_remaining_idx" ON "xstore_poultry_farm_lots" ("tenant_id","remaining_kg");
CREATE TABLE IF NOT EXISTS "xstore_poultry_farm_movements" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,"tenant_id" uuid NOT NULL REFERENCES "xstore_tenants"("id") ON DELETE cascade,"lot_id" uuid REFERENCES "xstore_poultry_farm_lots"("id") ON DELETE set null,"invoice_id" uuid REFERENCES "xstore_poultry_invoices"("id") ON DELETE set null,"actor_user_id" uuid REFERENCES "xstore_users"("id") ON DELETE set null,"movement_type" text NOT NULL,"product_name" text NOT NULL,"quantity_kg" numeric(12,3) NOT NULL,"unit_cost" numeric(12,2) NOT NULL,"total_cost" numeric(12,2) NOT NULL,"note" text,"created_at" timestamptz DEFAULT now() NOT NULL);
CREATE INDEX IF NOT EXISTS "xstore_poultry_farm_movements_tenant_created_idx" ON "xstore_poultry_farm_movements" ("tenant_id","created_at");
CREATE INDEX IF NOT EXISTS "xstore_poultry_farm_movements_tenant_product_idx" ON "xstore_poultry_farm_movements" ("tenant_id","product_name");
CREATE INDEX IF NOT EXISTS "xstore_poultry_farm_movements_invoice_idx" ON "xstore_poultry_farm_movements" ("invoice_id");
